// JAH demo program — runnable with: node demo.js
// Record JAH-APX6-000015 — Compounded integration and acceptance suite
// Machine-checked verification: each claimed identity is recomputed and checked.
'use strict';
var checks = [{"expr": "812+340+52", "expect": 1204}, {"expr": "1204-52", "expect": 1152}, {"expr": "3*401+1", "expect": 1204}];
var fails = 0;
checks.forEach(function (ch) {
